function playSound(){try{const c=new (window.AudioContext||window.webkitAudioContext)();[740,1040].forEach((f,i)=>{const osc=c.createOscillator(),g=c.createGain();osc.type='sine';osc.frequency.value=f;osc.connect(g);g.connect(c.destination);g.gain.value=.07;osc.start(c.currentTime+i*.18);osc.stop(c.currentTime+i*.18+.13)});setTimeout(()=>c.close(),600)}catch(e){}}
